// Klient ZAIMPORTOWAL certyfikat serwera do wlasnego truststore - polaczenie OK
HttpClient trustingClient = HttpClient.newBuilder().sslContext(customSslContext).build();
trustingClient.send(request, BodyHandlers.ofString()); // 200 OK - handshake udany

// Klient z DOMYSLNYM truststore - NIE zna samopodpisanego certyfikatu
HttpClient defaultClient = HttpClient.newHttpClient();
try {
    defaultClient.send(request, BodyHandlers.ofString());
} catch (SSLHandshakeException e) {
    System.out.println("Certyfikat ODRZUCONY - nie jest podpisany przez zaufany, publiczny CA");
}

// ZLE (decyzja wdrozeniowa): publiczny serwer produkcyjny z SAMOPODPISANYM certyfikatem
// kazdy odwiedzajacy widzi ostrzezenie przegladarki "polaczenie nie jest prywatne"
// i musi recznie je zaakceptowac - przyzwyczaja to do ignorowania takich ostrzezen

// DOBRZE (decyzja wdrozeniowa): certyfikat od zaufanego CA (np. Let's Encrypt)
// ZERO ostrzezen przegladarki, ZERO recznego importowania do truststore klientow -
// dziala "od razu" dla kazdego odwiedzajacego, tak jak certyfikaty duzych serwisow
